const BALANCE_INITIAL=1000;
const accounts=[
{name:'Breakout 10K #1',prop:'Breakout',size:10000,status:'Live',cost:40,date:null,meta:'Coste $40'},
{name:'Breakout 10K #2',prop:'Breakout',size:10000,status:'Live',cost:40,date:null,meta:'Coste $40'},
{name:'Breakout 25K',prop:'Breakout',size:25000,status:'Challenge',cost:130,date:null,meta:'Coste $130 · modalidad distinta a 2 Steps'},
{name:'Orion 5K',prop:'Orion',size:5000,status:'Live',cost:50,date:null,meta:'Coste $50'},
{name:'BitFunded 5K',prop:'BitFunded',size:5000,status:'Live',cost:49,date:null,meta:'Coste $49'},
{name:'BitFunded 10K #1',prop:'BitFunded',size:10000,status:'Challenge',cost:49.5,date:null,meta:'2 Steps · coste imputado $49.50'},
{name:'BitFunded 10K #2',prop:'BitFunded',size:10000,status:'Challenge',cost:49.5,date:null,meta:'2 Steps · coste imputado $49.50'},
{name:'BitFunded 25K #1',prop:'BitFunded',size:25000,status:'Challenge',cost:124.5,date:null,meta:'2 Steps · coste imputado $124.50'},
{name:'BitFunded 25K #2',prop:'BitFunded',size:25000,status:'Challenge',cost:124.5,date:null,meta:'2 Steps · coste imputado $124.50'}
];
const moves=[
{name:'Compra Breakout 10K #2',type:'Compra',prop:'Breakout',amount:-40,date:null},
{name:'Compra Orion 5K',type:'Compra',prop:'Orion',amount:-50,date:null},
{name:'Compra Breakout 10K #1',type:'Compra',prop:'Breakout',amount:-40,date:null},
{name:'Compra BitFunded 25K x2',type:'Compra',prop:'BitFunded',amount:-249,date:null},
{name:'Compra Breakout 25K',type:'Compra',prop:'Breakout',amount:-130,date:null},
{name:'Compra BitFunded 5K',type:'Compra',prop:'BitFunded',amount:-49,date:null},
{name:'Compra BitFunded 10K x2',type:'Compra',prop:'BitFunded',amount:-99,date:null}
];
const money=v=>'$'+Math.abs(v).toLocaleString('en-US',{maximumFractionDigits:2});
const signedMoney=v=>(v<0?'-$':'$')+Math.abs(v).toLocaleString('en-US',{maximumFractionDigits:2});
const k=v=>'$'+(v/1000).toLocaleString('en-US',{maximumFractionDigits:1}).replace('.0','')+'K';
const pct=v=>(isFinite(v)?v:0).toFixed(1)+'%';
function periodMatch(date,p){return p==='total'||(date&&date.slice(0,7)===p)}
function render(p){
const monthMode=p!=='total';
const fm=moves.filter(m=>periodMatch(m.date,p));
const fa=accounts.filter(a=>periodMatch(a.date,p));
const spent=-fm.filter(m=>m.amount<0).reduce((s,m)=>s+m.amount,0);
const paid=fm.filter(m=>m.amount>0).reduce((s,m)=>s+m.amount,0);
const net=paid-spent;
const liveAcc=(monthMode?fa:accounts).filter(a=>a.status==='Live');
const challengeAcc=(monthMode?fa:accounts).filter(a=>a.status==='Challenge');
const capitalLive=liveAcc.reduce((s,a)=>s+a.size,0);
const capitalChallenge=challengeAcc.reduce((s,a)=>s+a.size,0);
const capitalBought=(monthMode?fa:accounts).reduce((s,a)=>s+a.size,0);
const ratio=capitalBought?capitalLive/capitalBought*100:0;
const ratioAccounts=(monthMode?fa:accounts).length?liveAcc.length/(monthMode?fa:accounts).length*100:0;
const bal=BALANCE_INITIAL+net;
document.getElementById('balance').textContent=money(bal);
document.getElementById('spent').textContent=money(spent);
document.getElementById('paid').textContent=money(paid);
document.getElementById('net').textContent=signedMoney(net);
document.getElementById('net').className='value '+(net>=0?'green':'red');
document.getElementById('funded').textContent=k(capitalLive);
document.getElementById('liveCount').textContent=liveAcc.length+' cuentas Live';
document.getElementById('fundingRatio').textContent=pct(ratio);
document.getElementById('fundingSmall').textContent=k(capitalLive)+' Live / '+k(capitalBought)+' comprado';
document.getElementById('capitalLive').textContent=k(capitalLive);
document.getElementById('capitalChallenge').textContent=k(capitalChallenge);
document.getElementById('ratioAccounts').textContent=pct(ratioAccounts);
document.getElementById('donutNumber').textContent=Math.round(ratio)+'%';
document.getElementById('donut').style.setProperty('--funding',Math.min(100,Math.max(0,ratio))+'%');
document.getElementById('breakeven').textContent=money(Math.max(0,spent-paid));
document.getElementById('recovery').textContent=spent?pct(paid/spent*100):'0%';
document.getElementById('roi').textContent=spent?pct(net/spent*100):'0%';
document.getElementById('roi').className='value '+(net>=0?'green':'red');
const monthLabel=p==='2026-08'?'Agosto 2026':'Total';
document.getElementById('subtitle').textContent=monthMode?'Vista mensual · '+monthLabel:'Situación actual · 20/08/2026';
document.getElementById('balanceSmall').textContent=monthMode?'Balance teórico del periodo desde $1.000':'Balance inicial $1.000';
const maxChart=Math.max(800,spent,paid); const y=v=>234-(Math.min(maxChart,v)/maxChart)*200;
const sy=y(spent),py=y(paid);
document.getElementById('spendLine').setAttribute('points',`70,234 650,${sy}`); document.getElementById('spendDot').setAttribute('cy',sy);
document.getElementById('paidLine').setAttribute('points',`70,234 650,${py}`); document.getElementById('paidDot').setAttribute('cy',py);
document.getElementById('spendLabel').textContent=money(spent); document.getElementById('spendLabel').setAttribute('y',Math.max(20,sy-12));
document.getElementById('paidLabel').textContent=money(paid); document.getElementById('paidLabel').setAttribute('y',Math.max(20,py-12));
document.getElementById('chartNote').textContent=monthMode?'Los movimientos históricos anteriores no tienen fecha exacta y solo aparecen en TOTAL. Desde el 20/08/2026 cada movimiento nuevo queda asignado automáticamente a su mes.':'No tenemos las fechas exactas de las compras anteriores. Por eso la gráfica arranca con el acumulado actual. A partir del próximo movimiento, los nuevos puntos sí quedarán registrados de forma cronológica.';
const props=['Breakout','Orion','BitFunded'];
document.getElementById('firmGrid').innerHTML=props.map(prop=>{
const aa=(monthMode?fa:accounts).filter(a=>a.prop===prop); const mm=fm.filter(m=>m.prop===prop); const sp=-mm.filter(m=>m.amount<0).reduce((s,m)=>s+m.amount,0); const pa=mm.filter(m=>m.amount>0).reduce((s,m)=>s+m.amount,0); const nl=pa-sp; const lv=aa.filter(a=>a.status==='Live').reduce((s,a)=>s+a.size,0);
return `<div class="firm-card"><div class="firm-head"><div><div class="firm-name">${prop}</div><div class="small">${aa.length} ${aa.length===1?'cuenta':'cuentas'}</div></div><div class="${nl>=0?'green':'red'}">${signedMoney(nl)} neto</div></div><div class="firm-metrics"><div><span class="label">Gastado</span><strong class="cyan">${money(sp)}</strong></div><div><span class="label">Payouts</span><strong class="pink">${money(pa)}</strong></div><div><span class="label">Live</span><strong class="green">${k(lv)}</strong></div></div></div>`;
}).join('');
const shown=monthMode?fa:accounts;
document.getElementById('accountList').innerHTML=shown.length?shown.map(a=>`<div class="account"><div><div class="name">${a.name}</div><div class="meta">${a.meta}</div><span class="badge ${a.status==='Live'?'green':'amber'}"><span class="dot"></span>${a.status==='Live'?'LIVE':'CHALLENGE'}</span></div><div class="amount">${k(a.size)}</div></div>`).join(''):`<div class="note">No hay cuentas con fecha de compra registrada en este mes. El histórico anterior se conserva en TOTAL.</div>`;
}
document.getElementById('period').addEventListener('change',e=>render(e.target.value));
render('total');